head.script:
scwin.onpageload = function() {
    input1.setValue("inputValue");
};
scwin.onpageunload = function() {};
scwin.fn_formatter2 = function(data) {
    console.log("formatter :" + data + "_test2");
    WebSquare.logger.printLog("formatter :" + data + "_test2");
    return data + "_test2";
};
scwin.fn_formatter = function(data) {
    console.log("formatter :" + data + "_test1");
    return data + "_test1";
};
scwin.trigger1_onclick = function(e) {
    input1.setDisplayFormatter(scwin.fn_formatter);
};
scwin.trigger2_onclick = function(e) {
    input1.setDisplayFormatter(scwin.fn_formatter2);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 'input.setDisplayFormat'버튼을 클릭한다.
    //1. After running the sample, click the 'input.setDisplayFormat' button.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 1. 왼쪽의 입력창에 'inputValue_test1'값이 보여진다.
    //1. The input window on the left shows the value of 'inputValue_test1'.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#input1').val() == 'inputValue_test1'", "true");
    //Test step 2. 그 상태에서 'input.setDisplayFormat'버튼을 클릭한다.
    //2. In that state, click the 'input.setDisplayFormat' button.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#input1').val() == 'inputValue_test2'", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 15-Jun-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
